PROJECT_ASSET_PREFIXES={'babbar-':'babbar-residency','opera-':'opera-home','essentia-':'essentia-salon','yogesh-zirakpur-':'yogesh-residence','evaan-joshi-':'evaan-joshi','falcon-66-':'falcon-66','sachdeva-125-':'sachdeva-125','tdi-wellington-':'tdi-wellington-3bhk','sheena-nail-':'sheena-3b2-nail-studio','prince-123-':'prince-residence','ruchit-phase1-':'ruchit-phase-1'}
def project_for_asset(name):
 for prefix,slug in PROJECT_ASSET_PREFIXES.items():
  if name.startswith(prefix): return slug
 return None
def image_path(name,variant):
 project=project_for_asset(name)
 folder=f'projects/{project}/photos/optimized' if project else 'images'
 candidate=f'{folder}/{name}-{variant}.webp'
 if not (ROOT/candidate).exists():
  for other in ['1920','1280','640']:
   fallback=f'{folder}/{name}-{other}.webp'
   if (ROOT/fallback).exists() and DIMS[name][other]==DIMS[name][variant]: return fallback
 return candidate
def img(name,alt,r='',cls='',eager=False,sizes='(max-width: 700px) 100vw, 60vw'):
 variants=DIMS[name]; seen=set(); sources=[]
 for requested in ['640','1280','1920']:
  width=variants[requested]['width']
  if width not in seen:sources.append(f'{r}{image_path(name,requested)} {width}w');seen.add(width)
 dim=variants['1280'];srcset=', '.join(sources)
 if name=='megha-professional': sizes='(max-width: 700px) 100vw, 42vw'
 return f'<img class="{cls}" src="{r}{image_path(name,"1280")}" srcset="{srcset}" sizes="{sizes}" width="{dim["width"]}" height="{dim["height"]}" alt="{e(alt)}" loading="{"eager" if eager else "lazy"}" decoding="async"'+(' fetchpriority="high"' if eager else '')+'>'

def discover_project_media(project):
 """Include supplied project originals and browser-ready clips even if content JSON missed them."""
 labels={
  'yogesh-zirakpur-alcove-progress':'Mandir alcove during the Yogesh Residence project',
  'yogesh-zirakpur-tv-wall-source':'Original TV wall photograph supplied for Yogesh Residence',
  'yogesh-zirakpur-wardrobe-source':'Original wardrobe photograph supplied for Yogesh Residence',
 }
 photo_dir=ROOT/'projects'/project['slug']/'photos'/'originals'
 known={item[0] for item in project.get('gallery',[])}
 omitted=set(project.get('omitGallery',[]))
 for photo in sorted(photo_dir.iterdir()) if photo_dir.exists() else []:
  if photo.is_file() and photo.suffix.lower() in {'.jpg','.jpeg','.png','.webp','.tif','.tiff'} and photo.stem not in known and photo.stem not in omitted:
   label=labels.get(photo.stem,photo.stem.replace('-',' ').replace('_',' '))
   project.setdefault('gallery',[]).append([photo.stem,f'{project["title"]} — {label}'])
   known.add(photo.stem)
 video_dir=ROOT/'projects'/project['slug']/'videos'/'optimized'
 existing=project.get('videos',[]);known_videos={Path(item['file']).name for item in existing}|{Path(item['playbackFile']).name for item in existing if item.get('playbackFile')}
 for clip in sorted(video_dir.glob('*.mp4')) if video_dir.exists() else []:
  if clip.name not in known_videos:
   existing.append({'file':clip.name,'caption':f'{project["title"]} walkthrough · {clip.stem}'})
 project['videos']=existing

for project in P:
 discover_project_media(project)

